compile.workshop:
variables {
    global:
        0: marker
}

//Optimize for size enabled
rule ("wait optimization") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(marker, 1);
        Wait(False, Ignore Condition);
        Wait(False, Ignore Condition);
        Wait(True, Ignore Condition);
        Wait(True, Abort When False);
        Set Global Variable(marker, 2);
    }
}

